        return None

    def pick_pos(*keys):
        for k in keys:
            p = as_pair(observation.get(k))
            if p is not None:
                return p
        return (0, 0)

    sx, sy = pick_pos("self_position", "agent_position", "position")
    ox, oy = pick_pos("opponent_position", "enemy_position", "target_position")

    gw = observation.get("grid_width", observation.get("width", 0))
    gh = observation.get("grid_height", observation.get("height", 0))
    try:
        gw = int(gw)
    except Exception:
        gw = 0
    try:
        gh = int(gh)
    except Exception:
        gh = 0

    env = observation.get("environment_name", observation.get("env", "resource_collection"))

    def move_toward(tx, ty):
        return [clamp_dir(tx - sx), clamp_dir(ty - sy)]

    def move_away(tx, ty):
        return [clamp_dir(sx - tx), clamp_dir(sy - ty)]

    def manhattan(a, b, c, d):
        return abs(a - c) + abs(b - d)

    def best_target(items, prefer_far_from_opponent=False):
        best = None
        best_score = None
        for item in items or []:
            p = as_pair(item)
            if p is None:
                continue
            x, y = p
            ds = manhattan(sx, sy, x, y)
            do = manhattan(ox, oy, x, y)
            score = ds * 2 - do if prefer_far_from_opponent else ds
            if best is None or score < best_score:
                best = p
                best_score = score
        return best

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            return move_toward(ox, oy)
        corners = [(0, 0)]
        if gw > 0 and gh > 0:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        target = None
        best_d = None
        for x, y in corners:
            d = manhattan(ox, oy, x, y)
            if target is None or d > best_d:
                target = (x, y)
                best_d = d
        return move_toward(target[0], target[1])

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("neutral_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        target = best_target(targets, prefer_far_from_opponent=True)
        if target is None:
            if gw > 0 and gh > 0:
                target = (gw // 2, gh // 2)
            else:
                return move_away(ox, oy)
        return move_toward(target[0], target[1])

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_target(resources, prefer_far_from_opponent=False)
    if target is not None:
        return move_toward(target[0], target[1])

    if gw > 0 and gh > 0:
        center = (gw // 2, gh // 2)
        if manhattan(sx, sy, center[0], center[1]) > 0:
            return move_toward(center[0], center[1])

    return move_away(ox, oy)

